// Police Unicode embarquee pour les PDF (recus, export comptable).
//
// Pourquoi : jsPDF n'embarque par defaut que les polices standard PDF (Helvetica,
// Times...), limitees a l'encodage WinAnsi = alphabet latin occidental. Tout ce qui
// sort de cet encodage sortait en charabia dans le PDF : le cyrillique (ru), mais
// aussi les lettres speciales du polonais, du turc, du vietnamien, du yoruba, du
// bambara, du wolof et du haoussa.
//
// Ce fichier contient DejaVu Sans (domaine public / licence Bitstream Vera, libre
// d'usage y compris commercial), sous-ensemble reduit aux ecritures latine,
// cyrillique et grecque + ponctuation, symboles monetaires et lettres africaines
// (IPA). Environ 105 Ko par graisse.
//
// Il est charge en import() dynamique UNIQUEMENT quand le texte du PDF contient un
// caractere hors WinAnsi : un recu en francais ne telecharge donc rien de plus.
//
// Non couvert par cette police (il faudrait un autre moteur de rendu, jsPDF ne sait
// pas faire le "shaping" arabe ni embarquer un jeu CJK complet) : arabe, ourdou,
// hebreu, devanagari, bengali, tamoul, telougou, thai, chinois, japonais, coreen,
// amharique.

export const PDF_FONT_REGULAR_B64 = "";

export const PDF_FONT_BOLD_B64 = "";
